package com.company.skillplatform.audit.interfaces;import com.company.skillplatform.audit.application.AuditService;import com.company.skillplatform.audit.infrastructure.entity.AuditLogEntity;import java.util.List;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/audit-logs")public class AuditController{private final AuditService service;public AuditController(AuditService s){service=s;}@GetMapping List<AuditLogEntity> list(@RequestParam String targetType,@RequestParam Long targetId){return service.list(targetType,targetId);}}
